pruning_source_updates.before_source:
INFO {
  TITLE: "cluster_assume"
  DESCRIPTION: "pure-input assumption replicated into each output cluster"
  SEMANTICS: Mealy
  TARGET: Mealy
}
MAIN {
  INPUTS { a; b; }
  OUTPUTS { x; y; }
  ASSUME { G a; }
  GUARANTEE {
    G (x <-> X a);
    G (y <-> X b);
  }
}

INFO {
  TITLE: "cluster_prune"
  DESCRIPTION: "global liveness assumption G F !r is kept in both clusters, including the disjoint one"
  SEMANTICS: Mealy
  TARGET: Mealy
}
MAIN {
  INPUTS { r; }
  OUTPUTS { g; h; }
  ASSUME {
    G F (!r);
  }
  GUARANTEE {
    G (r -> X g);
    G F h;
  }
}
